import {SERVICE_PRESETS,normalizeServiceProfile} from '../data/qrk-service-presets.js';
export const BAND_COLORS=['#C8553D','#2F6F5E','#3A4A7A','#8A6A3B','#A23B2A','#5B4B8A','#2D5D7B','#6B7A2F'];
export const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const profileOf=client=>normalizeServiceProfile(client.serviceProfile||{preset:'quick'});
export const serviceLabel=client=>{const profile=profileOf(client);return profile.serviceModes.length===2?'Quick + Table':SERVICE_PRESETS[profile.preset].name};
export const bandColor=name=>{let hash=0;for(const char of String(name))hash=(hash*31+char.charCodeAt(0))%8;return BAND_COLORS[hash]};
export const clientStatus=(client,statuses)=>client.status==='paused'?'paused':statuses?.get(client.admin?.username)?.mustChangePassword===true?'pending':'active';
const needsAttention=(client,statuses)=>clientStatus(client,statuses)!=='active';
const matchers={all:()=>true,quick:client=>profileOf(client).serviceModes.includes('quick'),table:client=>profileOf(client).serviceModes.includes('table'),paused:client=>client.status==='paused',attention:needsAttention};
export const filterClients=(clients,{query='',filter='all'}={},statuses=null)=>{const q=String(query).trim().toLowerCase(),match=matchers[filter]||matchers.all;return clients.filter(client=>match(client,statuses)&&(!q||[client.businessName,client.prefix,client.admin?.name].some(field=>String(field??'').toLowerCase().includes(q))))};
export const filterCounts=(clients,statuses)=>Object.fromEntries(Object.keys(matchers).map(key=>[key,filterClients(clients,{filter:key},statuses).length]));
export const overviewStats=(clients,statuses)=>{const states=clients.map(client=>clientStatus(client,statuses)),attention=clients.filter(client=>needsAttention(client,statuses)),mix=new Map();for(const client of clients){const label=serviceLabel(client);mix.set(label,(mix.get(label)||0)+1)}return{total:clients.length,active:clients.filter(client=>client.status==='active').length,paused:states.filter(state=>state==='paused').length,pending:states.filter(state=>state==='pending').length,attention:attention.slice(0,3).map(client=>client.businessName),attentionCount:attention.length,mix:[...mix].map(([label,count])=>({label,count})).sort((a,b)=>b.count-a.count)}};
const pillText={active:'Active',paused:'Paused',pending:'First login pending'};
const pill=state=>`<span class="admin-status-pill is-${state}">${pillText[state]}</span>`;
export const clientCard=(client,{hosted=false,statuses=null}={})=>{const state=clientStatus(client,statuses),profile=profileOf(client);return `<article class="admin-client-card" data-client-id="${esc(client.id)}"><span class="admin-client-band" style="background:${bandColor(client.businessName)}"></span><span class="admin-client-initial">${esc(String(client.businessName).charAt(0).toUpperCase())}</span>${pill(state)}<strong>${esc(client.businessName)}</strong><small>${esc(serviceLabel(client))} · ${esc(profile.locationName)} · ${esc(client.prefix)}.</small><div class="admin-client-actions"><button class="button primary" type="button" data-open-client>${hosted?'Client sign-in':'Preview as admin'}</button><button class="button outline" type="button" data-manage-client>Manage</button></div></article>`};
export const manageSheetBody=(client,{hosted=false,statuses=null}={})=>{const login=statuses?.get((client.admin||{}).username)?.mustChangePassword,active=client.status==='active',admin=client.admin||{};return `<div class="admin-manage" data-client-id="${esc(client.id)}"><section><h3>Client Admin</h3><p>${esc(admin.name)}</p><p>${esc(admin.email)}</p><code>${esc(admin.username)}</code>${login===true?'<span class="admin-login-status">First login pending</span>':login===false?'<span class="admin-login-status">Password set</span>':''}${active?'<button class="button outline" type="button" data-reset-client-password>Reset temporary password</button>':''}</section><section><h3>Portal</h3><p>${esc(client.prefix)}.</p><p>${esc(serviceLabel(client))}</p>${active?'<a class="button outline" href="/?client-login=1" target="_blank" rel="noopener">Open client login</a>':''}<a class="button outline" href="/menu/?business=${encodeURIComponent(client.slug)}">Customer view</a><button class="button outline" type="button" data-configure-client>Configure</button></section><section class="admin-manage-danger"><h3>${active?'Pause this client':'Activate this client'}</h3><p>${active?'Staff and customers lose access until you reactivate it.':'Staff and customers regain access.'}</p><button class="button subtle ${active?'is-danger':'is-accent'}" type="button" data-toggle-client>${active?'Pause':'Activate'}</button></section></div>`};
export const adminRow=(client,statuses=null)=>{const admin=client.admin||{},initials=String(admin.name||'').split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0].toUpperCase()).join('');return `<article class="admin-account-row" data-client-id="${esc(client.id)}"><span class="admin-avatar">${esc(initials)}</span><div><strong>${esc(admin.name)}</strong><small>${esc(admin.email)}</small></div><span>${esc(client.businessName)}</span><code>${esc(admin.username)}</code>${pill(clientStatus(client,statuses))}<button class="button subtle" type="button" data-reset-client-password>Reset password</button></article>`};
